-- T1a · the served shape of contoso_served.v_contoso_order_line — column names and types the body produces (compared to data/datasets/v_contoso_order_line.yaml below)
DESCRIBE SELECT r."OrderKey",
       r."RowNumber",
       o."DT" AS OrderDate,
       o."DeliveryDate",
       o."CustomerKey",
       o."StoreKey",
       r."ProductKey",
       o."CurrencyCode",
       r."Quantity",
       r."UnitPrice",
       r."NetPrice",
       r."UnitCost"
FROM main.orderrows r
JOIN main.orders o ON o."OrderKey" = r."OrderKey";

