--           DeliveryDate | TIMESTAMP | YES | NULL | NULL | NULL
--           CustomerKey | INTEGER | YES | NULL | NULL | NULL
--           StoreKey | INTEGER | YES | NULL | NULL | NULL
--           ProductKey | INTEGER | YES | NULL | NULL | NULL
