-- ================================================================================================
-- T1b · the served shape of contoso_served.dim_contoso_product — column names and types the body produces (compared to data/datasets/dim_contoso_product.yaml below)
DESCRIBE WITH color_spelling AS (                 -- how often each SPELLING of a colour is used
    SELECT "Color" AS color_raw, count(*) AS rows_with_spelling
    FROM main.product
    WHERE "Color" IS NOT NULL
    GROUP BY 1
),
color_canon AS (                         -- one canonical spelling per case-insensitive colour
    SELECT lower(color_raw) AS color_lc, color_raw AS color_canonical
    FROM (SELECT color_raw,
                 row_number() OVER (PARTITION BY lower(color_raw)
                                    ORDER BY rows_with_spelling DESC, color_raw) AS rn
          FROM color_spelling)
    WHERE rn = 1
)
SELECT p."ProductKey",
       p."ProductCode",
       p."ProductName",
       p."Manufacturer",
       p."Brand",
       coalesce(cc.color_canonical, p."Color") AS Color,
       nullif(p."WeightUnit", '') AS WeightUnit,
       p."Weight",
       p."Cost",
       p."Price",
       p."CategoryKey",
       p."CategoryName",
       p."SubCategoryKey",
       p."SubCategoryName"
FROM main.product p
LEFT JOIN color_canon cc ON cc.color_lc = lower(p."Color");

--   ANSWER: column_name | column_type | null | key | default | extra
--           ProductKey | INTEGER | YES | NULL | NULL | NULL
--           ProductCode | VARCHAR | YES | NULL | NULL | NULL
--           ProductName | VARCHAR | YES | NULL | NULL | NULL
--           Manufacturer | VARCHAR | YES | NULL | NULL | NULL
--           Brand | VARCHAR | YES | NULL | NULL | NULL
--           Color | VARCHAR | YES | NULL | NULL | NULL
--           WeightUnit | VARCHAR | YES | NULL | NULL | NULL
--           Weight | DECIMAL(20,5) | YES | NULL | NULL | NULL
--           Cost | DECIMAL(20,5) | YES | NULL | NULL | NULL
--           Price | DECIMAL(20,5) | YES | NULL | NULL | NULL
--           CategoryKey | INTEGER | YES | NULL | NULL | NULL
--           CategoryName | VARCHAR | YES | NULL | NULL | NULL
--           SubCategoryKey | INTEGER | YES | NULL | NULL | NULL
--           SubCategoryName | VARCHAR | YES | NULL | NULL | NULL

