-- T2a · the grain of contoso_served.v_contoso_order_line: rows, distinct cell keys, duplicate keys, null key parts
SELECT count(*) AS served_rows,
       count(DISTINCT ("OrderKey", "RowNumber")) AS distinct_keys,
       count(*) - count(DISTINCT ("OrderKey", "RowNumber")) AS duplicate_keys,
       count(*) FILTER (WHERE "OrderKey" IS NULL) + count(*) FILTER (WHERE "RowNumber" IS NULL) AS null_key_parts
FROM (
SELECT r."OrderKey",
       r."RowNumber",
       o."DT" AS OrderDate,
       o."DeliveryDate",
       o."CustomerKey",
       o."StoreKey",
       r."ProductKey",
       o."CurrencyCode",
       r."Quantity",
       r."UnitPrice",
       r."NetPrice",
       r."UnitCost"
FROM main.orderrows r
JOIN main.orders o ON o."OrderKey" = r."OrderKey"
) t;

