  UNION ALL SELECT 'date.DayofWeek' AS served_text_column, count(*) AS n FROM main.date WHERE "DayofWeek" = ''
  UNION ALL SELECT 'date.DayofWeekShort' AS served_text_column, count(*) AS n FROM main.date WHERE "DayofWeekShort" = ''
  UNION ALL SELECT 'currencyexchange.FromCurrency' AS served_text_column, count(*) AS n FROM main.currencyexchange WHERE "FromCurrency" = ''
  UNION ALL SELECT 'currencyexchange.ToCurrency' AS served_text_column, count(*) AS n FROM main.currencyexchange WHERE "ToCurrency" = ''
) WHERE n > 0 ORDER BY n DESC;

--   ANSWER: served_text_column | n
--           product.WeightUnit | 222
--           store.Status | 58

-- ================================================================================================
-- T10 · whitespace sweep over the same 33 pairs — is any served text value padded (i.e. does any column need a trim the transforms do not write)?
SELECT * FROM (
  SELECT 'orders.CurrencyCode' AS served_text_column, count(*) AS n FROM main.orders WHERE "CurrencyCode" <> trim("CurrencyCode")
  UNION ALL SELECT 'product.ProductCode' AS served_text_column, count(*) AS n FROM main.product WHERE "ProductCode" <> trim("ProductCode")
  UNION ALL SELECT 'product.ProductName' AS served_text_column, count(*) AS n FROM main.product WHERE "ProductName" <> trim("ProductName")
  UNION ALL SELECT 'product.Manufacturer' AS served_text_column, count(*) AS n FROM main.product WHERE "Manufacturer" <> trim("Manufacturer")
  UNION ALL SELECT 'product.Brand' AS served_text_column, count(*) AS n FROM main.product WHERE "Brand" <> trim("Brand")
  UNION ALL SELECT 'product.Color' AS served_text_column, count(*) AS n FROM main.product WHERE "Color" <> trim("Color")
  UNION ALL SELECT 'product.WeightUnit' AS served_text_column, count(*) AS n FROM main.product WHERE "WeightUnit" <> trim("WeightUnit")
  UNION ALL SELECT 'product.CategoryName' AS served_text_column, count(*) AS n FROM main.product WHERE "CategoryName" <> trim("CategoryName")
  UNION ALL SELECT 'product.SubCategoryName' AS served_text_column, count(*) AS n FROM main.product WHERE "SubCategoryName" <> trim("SubCategoryName")
  UNION ALL SELECT 'store.CountryCode' AS served_text_column, count(*) AS n FROM main.store WHERE "CountryCode" <> trim("CountryCode")
  UNION ALL SELECT 'store.CountryName' AS served_text_column, count(*) AS n FROM main.store WHERE "CountryName" <> trim("CountryName")
  UNION ALL SELECT 'store.State' AS served_text_column, count(*) AS n FROM main.store WHERE "State" <> trim("State")
  UNION ALL SELECT 'store.Description' AS served_text_column, count(*) AS n FROM main.store WHERE "Description" <> trim("Description")
  UNION ALL SELECT 'store.Status' AS served_text_column, count(*) AS n FROM main.store WHERE "Status" <> trim("Status")
  UNION ALL SELECT 'customer.Continent' AS served_text_column, count(*) AS n FROM main.customer WHERE "Continent" <> trim("Continent")
  UNION ALL SELECT 'customer.CountryFull' AS served_text_column, count(*) AS n FROM main.customer WHERE "CountryFull" <> trim("CountryFull")
  UNION ALL SELECT 'customer.Country' AS served_text_column, count(*) AS n FROM main.customer WHERE "Country" <> trim("Country")
  UNION ALL SELECT 'customer.StateFull' AS served_text_column, count(*) AS n FROM main.customer WHERE "StateFull" <> trim("StateFull")
  UNION ALL SELECT 'customer.State' AS served_text_column, count(*) AS n FROM main.customer WHERE "State" <> trim("State")
  UNION ALL SELECT 'customer.City' AS served_text_column, count(*) AS n FROM main.customer WHERE "City" <> trim("City")
  UNION ALL SELECT 'customer.ZipCode' AS served_text_column, count(*) AS n FROM main.customer WHERE "ZipCode" <> trim("ZipCode")
  UNION ALL SELECT 'customer.Gender' AS served_text_column, count(*) AS n FROM main.customer WHERE "Gender" <> trim("Gender")
  UNION ALL SELECT 'date.DateKey' AS served_text_column, count(*) AS n FROM main.date WHERE "DateKey" <> trim("DateKey")
  UNION ALL SELECT 'date.YearQuarter' AS served_text_column, count(*) AS n FROM main.date WHERE "YearQuarter" <> trim("YearQuarter")
  UNION ALL SELECT 'date.Quarter' AS served_text_column, count(*) AS n FROM main.date WHERE "Quarter" <> trim("Quarter")
  UNION ALL SELECT 'date.YearMonth' AS served_text_column, count(*) AS n FROM main.date WHERE "YearMonth" <> trim("YearMonth")
  UNION ALL SELECT 'date.YearMonthShort' AS served_text_column, count(*) AS n FROM main.date WHERE "YearMonthShort" <> trim("YearMonthShort")
  UNION ALL SELECT 'date.Month' AS served_text_column, count(*) AS n FROM main.date WHERE "Month" <> trim("Month")
  UNION ALL SELECT 'date.MonthShort' AS served_text_column, count(*) AS n FROM main.date WHERE "MonthShort" <> trim("MonthShort")
  UNION ALL SELECT 'date.DayofWeek' AS served_text_column, count(*) AS n FROM main.date WHERE "DayofWeek" <> trim("DayofWeek")
  UNION ALL SELECT 'date.DayofWeekShort' AS served_text_column, count(*) AS n FROM main.date WHERE "DayofWeekShort" <> trim("DayofWeekShort")
  UNION ALL SELECT 'currencyexchange.FromCurrency' AS served_text_column, count(*) AS n FROM main.currencyexchange WHERE "FromCurrency" <> trim("FromCurrency")
