-- ================================================================================================
-- T11a · UNFIXED · line numbering: does RowNumber start at 0, and how many orders have gaps?
SELECT count(*)                                                        AS orders_with_lines,
       count(*) FILTER (WHERE min_rn <> 0)                             AS orders_not_starting_at_zero,
       count(*) FILTER (WHERE max_rn + 1 <> n_lines)                   AS orders_with_gaps
FROM (SELECT "OrderKey", min("RowNumber") AS min_rn, max("RowNumber") AS max_rn, count(*) AS n_lines
      FROM main.orderrows GROUP BY 1);

--   ANSWER: orders_with_lines | orders_not_starting_at_zero | orders_with_gaps
--           93470 | 0 | 1448

-- ================================================================================================
-- T11b · UNFIXED · the indistinguishable lines: ROW PAIRS that agree on the order, the product and all four figures (this is NOT P2's G14, which asked a different question — see T11b2)
SELECT count(*) AS groups, sum(n) AS rows_in_those_groups, max(n) AS largest_group
FROM (SELECT "OrderKey", "ProductKey", "Quantity", "UnitPrice", "NetPrice", "UnitCost", count(*) AS n
      FROM main.orderrows GROUP BY 1,2,3,4,5,6 HAVING count(*) > 1);

--   ANSWER: groups | rows_in_those_groups | largest_group
--           8 | 16 | 2

-- ================================================================================================
-- T11b2 · the same defect counted P2's way (whole (OrderKey, ProductKey) group agrees), and the group-size split that reconciles 7/14 with T11b's 8/16
SELECT (SELECT count(*) FROM (SELECT "OrderKey","ProductKey" FROM main.orderrows GROUP BY 1,2
          HAVING count(*) > 1 AND count(DISTINCT ("Quantity","UnitPrice","NetPrice","UnitCost")) = 1))
                                                                       AS p2_g14_groups_all_rows_agree,
       (SELECT count(*) FROM (SELECT "OrderKey","ProductKey" FROM main.orderrows GROUP BY 1,2
          HAVING count(*) > 1))                                        AS colliding_key_groups,
       (SELECT count(*) FROM (SELECT "OrderKey","ProductKey" FROM main.orderrows GROUP BY 1,2
          HAVING count(*) = 3))                                        AS groups_of_three_rows;

--   ANSWER: p2_g14_groups_all_rows_agree | colliding_key_groups | groups_of_three_rows
--           7 | 260 | 1

-- ================================================================================================
-- T11c · UNFIXED · the sentinel store: its values, and how much of the fact points at it
SELECT (SELECT count(*) FROM main.store WHERE "StoreKey" = 999999)                AS sentinel_rows,
       (SELECT "StoreCode"   FROM main.store WHERE "StoreKey" = 999999)           AS sentinel_storecode,
       (SELECT "GeoAreaKey"  FROM main.store WHERE "StoreKey" = 999999)           AS sentinel_geoareakey,
       (SELECT "CountryCode" FROM main.store WHERE "StoreKey" = 999999)           AS sentinel_countrycode,
       (SELECT "CountryName" FROM main.store WHERE "StoreKey" = 999999)           AS sentinel_countryname,
       (SELECT "State"       FROM main.store WHERE "StoreKey" = 999999)           AS sentinel_state,
       (SELECT count(*) FROM main.orderrows r JOIN main.orders o USING ("OrderKey")
         WHERE o."StoreKey" = 999999)                                             AS lines_on_sentinel,
       (SELECT count(*) FROM main.orderrows)                                      AS lines_total;

--   ANSWER: sentinel_rows | sentinel_storecode | sentinel_geoareakey | sentinel_countrycode | sentinel_countryname | sentinel_state | lines_on_sentinel | lines_total
--           1 | -1 | -1 | -- | Online | Online | 93550 | 223974

-- ================================================================================================
-- T11d · UNFIXED · GeoAreaKey: is there anything in this warehouse to resolve it against?
SELECT (SELECT count(DISTINCT "GeoAreaKey") FROM main.customer)                   AS geo_in_customer,
       (SELECT count(DISTINCT "GeoAreaKey") FROM main.store)                      AS geo_in_store,
       (SELECT count(*) FROM (SELECT DISTINCT "GeoAreaKey" FROM main.store
                              EXCEPT SELECT "GeoAreaKey" FROM main.customer))     AS store_geo_not_in_customer,
       (SELECT count(*) FROM information_schema.tables
         WHERE table_schema = 'main' AND lower(table_name) LIKE '%geo%')          AS geography_relations;

--   ANSWER: geo_in_customer | geo_in_store | store_geo_not_in_customer | geography_relations
--           608 | 67 | 4 | 0

-- ================================================================================================
-- T11e · UNFIXED-BY-EXCLUSION · customer.Age: what year is it as-of, and is it served?
SELECT count(*)                                                        AS customer_rows,
       count(DISTINCT year("Birthday") + "Age")                        AS distinct_asof_years,
       min(year("Birthday") + "Age")                                   AS asof_min,
       max(year("Birthday") + "Age")                                   AS asof_max,
       (SELECT max(year("DT")) FROM main.orders)                        AS last_order_year,
       count(*) FILTER (WHERE "StartDT" = "EndDT")                     AS zero_length_validity_windows
FROM main.customer;

--   ANSWER: customer_rows | distinct_asof_years | asof_min | asof_max | last_order_year | zero_length_validity_windows
--           104990 | 2 | 2020 | 2021 | 2025 | 1

-- ================================================================================================
-- T11f · UNFIXED · the calendar's reach past the facts, and the two type mismatches it carries
SELECT (SELECT count(*) FROM main.date)                                           AS calendar_days,
       (SELECT count(*) FROM main.date d
         WHERE d."Date" > (SELECT max("DeliveryDate") FROM main.orders))           AS days_after_last_fact,
       (SELECT count(*) FROM main.date d
         WHERE NOT EXISTS (SELECT 1 FROM main.orders o WHERE o."DT" = d."Date"))   AS days_with_no_order,
       (SELECT count(DISTINCT "WorkingDay") FROM main.date)                        AS workingday_values,
       (SELECT min("WorkingDay") FROM main.date)                                   AS workingday_min,
       (SELECT max("WorkingDay") FROM main.date)                                   AS workingday_max,
       (SELECT min("DateKey") FROM main.date)                                      AS datekey_min,
       (SELECT max("DateKey") FROM main.date)                                      AS datekey_max;

--   ANSWER: calendar_days | days_after_last_fact | days_with_no_order | workingday_values | workingday_min | workingday_max | datekey_min | datekey_max
--           4018 | 359 | 568 | 2 | 0 | 1 | 20160101 | 20261231

-- ================================================================================================
-- T11g · UNFIXED · store versioning: codes, versions, and codes carrying more than one version
SELECT count(*)                                              AS store_rows,
       count(DISTINCT "StoreCode")                           AS store_codes,
       (SELECT count(*) FROM (SELECT "StoreCode" FROM main.store
                              GROUP BY 1 HAVING count(*) > 1)) AS codes_with_versions,
       (SELECT max(n) FROM (SELECT count(*) AS n FROM main.store GROUP BY "StoreCode")) AS max_versions_per_code
FROM main.store;

--   ANSWER: store_rows | store_codes | codes_with_versions | max_versions_per_code
--           74 | 67 | 6 | 3

-- ================================================================================================
-- T13a · padded_label: which region labels carry whitespace, how many spellings that costs, and whether the trimmed form already exists as its own value
SELECT (SELECT count(*) FROM main.customer WHERE "State" <> trim("State"))          AS state_padded_rows,
       (SELECT count(*) FROM main.customer WHERE "StateFull" <> trim("StateFull"))  AS statefull_padded_rows,
       (SELECT count(DISTINCT "State") FROM main.customer)                          AS state_spellings,
       (SELECT count(DISTINCT trim("State")) FROM main.customer)                    AS state_spellings_trimmed,
       (SELECT count(DISTINCT "StateFull") FROM main.customer)                      AS statefull_spellings,
       (SELECT count(DISTINCT trim("StateFull")) FROM main.customer)                AS statefull_spellings_trimmed;

--   ANSWER: state_padded_rows | statefull_padded_rows | state_spellings | state_spellings_trimmed | statefull_spellings | statefull_spellings_trimmed
--           4 | 4 | 565 | 563 | 610 | 608

-- ================================================================================================
-- T13b · the padded values spelled out beside their unpadded twins — same region or two regions? (GeoAreaKey / Country / Continent decide it)
SELECT "StateFull" AS statefull, "GeoAreaKey" AS geoareakey, "Country" AS country,
       "Continent" AS continent, count(*) AS n
FROM main.customer
WHERE trim("StateFull") IN (SELECT trim("StateFull") FROM main.customer
                            WHERE "StateFull" <> trim("StateFull"))
GROUP BY 1,2,3,4 ORDER BY 1,2;

--   ANSWER: statefull | geoareakey | country | continent | n
--           Birmingham | 93 | GB | Europe | 38
--           Birmingham  | 93 | GB | Europe | 3
--           Bradford | 102 | GB | Europe | 35
--           Bradford  | 102 | GB | Europe | 1

-- ================================================================================================
-- T13c · does the trim break the dependence P2 measured (StateFull -> State, GeoAreaKey, Country, Continent), and does the split reach the fact?
SELECT (SELECT count(*) FROM (SELECT "StateFull" FROM main.customer GROUP BY 1
          HAVING count(DISTINCT ("State","GeoAreaKey","Country","Continent")) > 1))
                                                                        AS violations_before_trim,
       (SELECT count(*) FROM (SELECT trim("StateFull") AS sf FROM main.customer GROUP BY 1
          HAVING count(DISTINCT (trim("State"),"GeoAreaKey","Country","Continent")) > 1))
                                                                        AS violations_after_trim,
       (SELECT count(*) FROM main.orderrows r JOIN main.orders o USING ("OrderKey")
          JOIN main.customer c USING ("CustomerKey")
         WHERE c."StateFull" <> trim(c."StateFull"))                    AS order_lines_affected;

--   ANSWER: violations_before_trim | violations_after_trim | order_lines_affected
--           0 | 0 | 13

-- ================================================================================================
-- T14 · UNFIXED/DISCLOSED · how much of each served dimension the fact never points at
SELECT (SELECT count(*) FROM main.customer)                                        AS customers,
       (SELECT count(*) FROM main.customer c WHERE NOT EXISTS
          (SELECT 1 FROM main.orders o WHERE o."CustomerKey" = c."CustomerKey"))    AS customers_never_ordering,
       (SELECT count(*) FROM main.store)                                           AS store_versions,
       (SELECT count(*) FROM main.store s WHERE NOT EXISTS
          (SELECT 1 FROM main.orders o WHERE o."StoreKey" = s."StoreKey"))          AS store_versions_never_selling;

--   ANSWER: customers | customers_never_ordering | store_versions | store_versions_never_selling
--           104990 | 52801 | 74 | 10

-- ================================================================================================
-- T12 · v_contoso_fx_rate_day needs no rule: is the grid complete, the self-rate exactly 1, every rate positive?
SELECT count(*)                                                          AS quote_rows,
       (SELECT count(*) FROM main.date) * count(DISTINCT "FromCurrency")
                                       * count(DISTINCT "ToCurrency")    AS complete_grid,
       count(*) FILTER (WHERE "FromCurrency" = "ToCurrency"
                          AND "Exchange" <> 1)                           AS self_rate_not_one,
       count(*) FILTER (WHERE "Exchange" <= 0)                           AS non_positive_rates,
       count(*) FILTER (WHERE "Exchange" IS NULL)                        AS null_rates
FROM main.currencyexchange;

--   ANSWER: quote_rows | complete_grid | self_rate_not_one | non_positive_rates | null_rates
--           100450 | 100450 | 0 | 0 | 0

